import express from 'express';
import path from 'path';
import { createServer as createViteServer } from 'vite';

interface SignalMessage {
  id: number;
  from: 'sender' | 'receiver';
  payload: any;
  timestamp: number;
}

interface Session {
  code: string;
  createdAt: number;
  lastActive: number;
  metadata: {
    files: Array<{ name: string; size: number; type: string }>;
    totalSize: number;
    expiryLabel?: string;
    password?: string;
    note?: string;
  };
  signals: SignalMessage[];
  signalSeq: number;
  status: 'waiting' | 'connecting' | 'transferring' | 'completed';
  relayChunks: Map<number, { data: string; fileIndex: number; totalChunks: number }>;
  relayTotalChunks: number;
}

const sessions = new Map<string, Session>();

// Cleanup stale sessions periodically (every 10 minutes)
setInterval(() => {
  const now = Date.now();
  for (const [code, sess] of sessions.entries()) {
    if (now - sess.lastActive > 24 * 60 * 60 * 1000) {
      sessions.delete(code);
    }
  }
}, 10 * 60 * 1000);

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(express.json({ limit: '50mb' }));
  app.use(express.urlencoded({ extended: true, limit: '50mb' }));

  // CORS headers
  app.use((req, res, next) => {
    res.header('Access-Control-Allow-Origin', '*');
    res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
    if (req.method === 'OPTIONS') {
      return res.sendStatus(200);
    }
    next();
  });

  // Health check
  app.get('/api/health', (req, res) => {
    res.json({ status: 'ok', activeSessions: sessions.size, timestamp: Date.now() });
  });

  // Create or register a transfer session
  app.post('/api/session/create', (req, res) => {
    const { code, metadata } = req.body;
    if (!code || !metadata) {
      return res.status(400).json({ error: 'Code and metadata are required' });
    }

    const cleanCode = code.toUpperCase().trim();
    const session: Session = {
      code: cleanCode,
      createdAt: Date.now(),
      lastActive: Date.now(),
      metadata,
      signals: [],
      signalSeq: 0,
      status: 'waiting',
      relayChunks: new Map(),
      relayTotalChunks: 0,
    };

    sessions.set(cleanCode, session);
    res.json({ ok: true, code: cleanCode });
  });

  // Get session details (Receiver lookup)
  app.get('/api/session/:code', (req, res) => {
    const code = req.params.code.toUpperCase().trim();
    const session = sessions.get(code);

    if (!session) {
      return res.status(404).json({ error: 'Session not found or expired' });
    }

    session.lastActive = Date.now();
    res.json({
      ok: true,
      session: {
        code: session.code,
        metadata: session.metadata,
        status: session.status,
        createdAt: session.createdAt,
      },
    });
  });

  // Receiver joins session
  app.post('/api/session/:code/join', (req, res) => {
    const code = req.params.code.toUpperCase().trim();
    const session = sessions.get(code);

    if (!session) {
      return res.status(404).json({ error: 'Session not found' });
    }

    session.status = 'connecting';
    session.lastActive = Date.now();

    // Notify sender that receiver has arrived
    session.signalSeq++;
    session.signals.push({
      id: session.signalSeq,
      from: 'receiver',
      payload: { type: 'receiver_joined' },
      timestamp: Date.now(),
    });

    res.json({ ok: true });
  });

  // Post signaling message (offer, answer, ice-candidate, progress status)
  app.post('/api/session/:code/signal', (req, res) => {
    const code = req.params.code.toUpperCase().trim();
    const { from, payload } = req.body;
    const session = sessions.get(code);

    if (!session) {
      return res.status(404).json({ error: 'Session not found' });
    }

    session.lastActive = Date.now();
    session.signalSeq++;
    session.signals.push({
      id: session.signalSeq,
      from,
      payload,
      timestamp: Date.now(),
    });

    // Keep max 200 signals
    if (session.signals.length > 200) {
      session.signals.splice(0, session.signals.length - 200);
    }

    res.json({ ok: true, seq: session.signalSeq });
  });

  // Poll for new signals
  app.get('/api/session/:code/signals', (req, res) => {
    const code = req.params.code.toUpperCase().trim();
    const afterSeq = parseInt(req.query.afterSeq as string, 10) || 0;
    const forRole = req.query.forRole as 'sender' | 'receiver';
    const session = sessions.get(code);

    if (!session) {
      return res.status(404).json({ error: 'Session not found' });
    }

    session.lastActive = Date.now();
    const newSignals = session.signals.filter((s) => {
      const isNew = s.id > afterSeq;
      const isForMe = forRole ? s.from !== forRole : true;
      return isNew && isForMe;
    });

    res.json({
      ok: true,
      currentSeq: session.signalSeq,
      signals: newSignals,
      status: session.status,
    });
  });

  // Fallback in-memory streaming relay: Post Chunk
  app.post('/api/session/:code/relay/chunk', (req, res) => {
    const code = req.params.code.toUpperCase().trim();
    const { chunkIndex, totalChunks, data, fileIndex } = req.body;
    const session = sessions.get(code);

    if (!session) {
      return res.status(404).json({ error: 'Session not found' });
    }

    session.lastActive = Date.now();
    session.relayTotalChunks = totalChunks;
    session.relayChunks.set(chunkIndex, { data, fileIndex, totalChunks });

    res.json({ ok: true, received: chunkIndex });
  });

  // Fallback in-memory streaming relay: Get Chunk
  app.get('/api/session/:code/relay/chunk', (req, res) => {
    const code = req.params.code.toUpperCase().trim();
    const chunkIndex = parseInt(req.query.chunkIndex as string, 10);
    const session = sessions.get(code);

    if (!session) {
      return res.status(404).json({ error: 'Session not found' });
    }

    session.lastActive = Date.now();
    const chunk = session.relayChunks.get(chunkIndex);

    if (!chunk) {
      return res.status(404).json({ ready: false });
    }

    // Return chunk and immediately free memory for delivered chunks
    res.json({
      ready: true,
      chunkIndex,
      data: chunk.data,
      fileIndex: chunk.fileIndex,
      totalChunks: chunk.totalChunks,
    });
  });

  // Clear relay chunks
  app.post('/api/session/:code/relay/clear', (req, res) => {
    const code = req.params.code.toUpperCase().trim();
    const session = sessions.get(code);
    if (session) {
      session.relayChunks.clear();
      session.status = 'completed';
    }
    res.json({ ok: true });
  });

  // Vite middleware for development vs Static files in production
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`Live P2P Signaling & Relay Server running on port ${PORT}`);
  });
}

startServer();
